parameters.jsCode:
const lastConnected = $input.first().json.last_connected_at;

// 1. Extrai o offset exato da string (ex: -04:00)
const dt = DateTime.fromISO(lastConnected, { setZone: true });
const offsetOriginal = dt.zoneName; // Isso retornará "UTC-4" ou similar

// 2. Aplica esse fuso específico ao horário atual
const agoraNoMesmoFuso = $now.setZone(offsetOriginal);

return {
  original: lastConnected,
  fuso_detectado: offsetOriginal,
  agora_no_fuso: agoraNoMesmoFuso.toISO(), // Formato ISO completo
  agora_formatado: agoraNoMesmoFuso.toFormat('yyyy-MM-dd HH:mm:ss') // Opcional
};
